<?php
require_once dirname(__DIR__).'/includes/functions.php';
$user=require_role('student');
$q=trim((string)($_GET['q']??''));$category=trim((string)($_GET['category']??''));
$sql="SELECT e.*,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id AND r.status<>'Cancelled') registered, EXISTS(SELECT 1 FROM registrations own WHERE own.event_id=e.id AND own.user_id=? AND own.status<>'Cancelled') already FROM events e WHERE e.deleted_at IS NULL AND e.event_date>=CURDATE()";
$params=[(int)$user['id']];if($q!==''){$sql.=' AND (e.title LIKE ? OR e.venue LIKE ? OR e.description LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}if($category!==''){$sql.=' AND e.category=?';$params[]=$category;}$sql.=' ORDER BY e.event_date,e.start_time';
$s=db()->prepare($sql);$s->execute($params);$events=$s->fetchAll();$cats=db()->query('SELECT DISTINCT category FROM events ORDER BY category')->fetchAll(PDO::FETCH_COLUMN);$pageTitle='Explore events';require dirname(__DIR__).'/includes/header.php';
?>
<div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><p class="text-primary small fw-bold text-uppercase mb-1">Find your people</p><h1 class="h2 fw-bold mb-0">Explore events</h1></div><form class="d-flex gap-2" method="get"><input class="form-control" name="q" placeholder="Search events" value="<?=e($q)?>"><select class="form-select" name="category"><option value="">All categories</option><?php foreach($cats as $cat):?><option <?= $category===$cat?'selected':''?>><?=e($cat)?></option><?php endforeach;?></select><button class="btn btn-primary">Filter</button></form></div>
<div class="row g-4"><?php foreach($events as $event):$left=max(0,(int)$event['max_participants']-(int)$event['registered']);$open=$event['status']==='Open'&&strtotime($event['reg_deadline'])>=time()&&$left>0&&!$event['already'];?><div class="col-md-6 col-xl-4"><article class="card card-hover h-100"><?php if($event['poster']):?><img class="poster card-img-top" src="<?=e(url('assets/uploads/posters/'.basename($event['poster'])))?>" alt="<?=e($event['title'])?>"><?php else:?><div class="poster d-grid text-center pt-5 text-primary fs-1"><i class="bi bi-calendar-event"></i></div><?php endif;?><div class="card-body d-flex flex-column"><div><span class="badge text-bg-light"><?=e($event['category'])?></span><h2 class="h5 mt-2"><?=e($event['title'])?></h2><p class="text-secondary small mb-2"><i class="bi bi-calendar3"></i> <?=e(date('M j, Y',strtotime($event['event_date'])))?> · <?=e(date('g:i A',strtotime($event['start_time'])))?></p><p class="text-secondary small"><i class="bi bi-geo-alt"></i> <?=e($event['venue'])?></p><p><?=e(mb_strimwidth($event['description'],0,120,'…'))?></p></div><div class="mt-auto d-flex justify-content-between align-items-center"><small><?=$left?> / <?=e((string)$event['max_participants'])?> seats left</small><?php if($event['already']):?><span class="badge text-bg-success">Registered</span><?php elseif($open):?><a class="btn btn-sm btn-primary" href="<?=e(url('student/register.php?event='.(int)$event['id']))?>">Register</a><?php else:?><button class="btn btn-sm btn-secondary" disabled><?= $left<1?'Full':($event['status']!=='Open'?'Closed':'Deadline passed')?></button><?php endif;?></div></div></article></div><?php endforeach;?><?php if(!$events):?><div class="col-12"><div class="card empty-state">No events match those filters.</div></div><?php endif;?></div>
<?php require dirname(__DIR__).'/includes/footer.php';?>
